    let gunLocked = false;
    let lockTarget = null;
    let GunPointer = null;
    let GunLine = null;
    // Lagged visual positions — smoothly trail behind real hand/target positions
    let lagSX = 0, lagSY = 0, lagSZ = 0; // origin (near hand)
