                                const t = getTransform(visualizer[i * 4 + j]);
                                t.method("set_position").invoke(offset);
                                t.method("set_rotation").invoke(rot);
                                visualizer[i * 4 + j].method("get_gameObject").invoke().method("SetActive").invoke(true);
